from pathlib import Path
import json,gzip,hashlib,datetime,subprocess,difflib
root=Path.cwd();out=Path('00_nucleo/diagnosticos/clippy-traits-formatacao-2026-10-16');assert json.loads((out/'seal-result.json').read_text())['exit']==0
package=Path('00_nucleo/materialization/clippy-traits-2026-10-16');(package/'proposed').mkdir(parents=True,exist_ok=False);sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
contracts={
 '00_nucleo/prompts/entities/decimal.md':'Implementar std::fmt::Display para Decimal, delegando à implementação Display de InnerDecimal. Retirar somente o método inerente público to_string; chamadas usuais e UFCS ToString usam o blanket ToString. Preservar texto decimal, escala/zeros e sinais no formato padrão, sem notação científica nova. FromStr não é adicionado: from_str continua Option e sua expectativa nominal permanece. Nenhum método aritmético/round/cast/Default ou campo muda.',
 '00_nucleo/prompts/entities/duration.md':'Implementar std::fmt::Display para Duration e retirar o método inerente público to_string. Renomear sua implementação corrigida para helper privado canonical_string, preservando exatamente o algoritmo u128 e o corpo atual; Display escreve essa string com f.write_str. ToString vem do blanket padrão. Preservar MIN/MAX/zero, sinais, frações e unidades; não alterar repr Typst, Neg, overflow aritmético ou as_*. A precisão/largura de Formatter não redefine a string canônica deste tipo.',
 '00_nucleo/prompts/entities/version.md':'Implementar std::fmt::Display para Version e retirar o método inerente público to_string. Renomear o corpo atual para helper privado canonical_string, Display escreve essa string com f.write_str e ToString vem do blanket padrão. Preservar componentes explícitos, trailing zeros, vazio e ordem; não tocar em PARITY_VERSION, igualdade/hash/ordem, at, parsers, casts ou repr Typst. A precisão/largura de Formatter não redefine sua string canônica. FromStr não é adicionado.',
 '00_nucleo/prompts/entities/style.md':'Implementar std::iter::FromIterator<Style> para Styles. Mover o mesmo fold ordenado de Style para StyleDelta ao trait, sem segundo backing/clones/reordenação. Conservar o método inerente público from_iter<I: IntoIterator<Item=Style>>(iter)->Self como adapter para <Self as FromIterator<Style>>::from_iter(iter). Preservar last-write-wins por campo, vazio, canais custom e todas as outras APIs. A implementação do trait resolve a ambiguidade nominal sem expect neste método.'}
base={}
for owner,contract in contracts.items():
 source=next(p for p in json.load(gzip.open(out/'before.json.gz'))['files'] if p.endswith('.rs') and ('00_nucleo/prompts/'+p.split('/src/',1)[1][:-3]+'.md')==owner)
 base[owner]=dict(text=Path(owner).read_text(),sha256=sha(owner),source=source,source_sha256=sha(source))
 proposed=base[owner]['text']+f'''\n\n## Traits Rust de formatação/construção — proposta 2026-10-16\n\n### Medição anterior à decisão\n\nO inventário anterior tem should_implement_trait em Styles.from_iter e inherent_to_string nos três tipos. As quatro implementações e os L0 vigentes foram lidos; fontes/hashes/HEAD/working tree/UTC/diffstat estão no base.json.gz deste pacote. Os dois parsers Option e os dois next de domínio foram classificados separadamente; não são alvo de conversão para traits. A sonda duration-before-probe e a correção interna anterior documentam a faixa i128 sem copiar o defeito. É mudança de contrato Rust, não mudança de linguagem Typst ou nova paridade medida.\n\n### Contrato proposto\n\n{contract}\n\nO contrato só materializa após confirmação humana ADR-0127 §2.1/2.4: existem três novos impls Display, um FromIterator e migração de três métodos inerentes públicos para o blanket ToString. Código genérico pode passar a depender desses traits; rollback pode quebrar esse código. A implementação não deve adicionar FromStr, novas variantes/campos, flags, defaults, fase, dependências ou supressões. Os comentários/exemplos antigos de to_string passam a significar a interface ToString, somente após ratificação.\n\n### Aceitação\n\nT1: usos genéricos Display+ToString e collect::<Styles> devem falhar antes por trait ausente e passar depois. T2: Decimal exibe 1.2300 sem perder zeros, preserva negativo/zero e mantém rejeições Option; Version exibe vazio e 1.2.0 preservando componentes. T3: Duration mantém textos corrigidos de MIN/MAX/MIN+1, zero e limites negativos, via format! e ToString. T4: collect vazio é vazio e Weight(400),Weight(700) produz weight Some(700), com demais campos inalterados; adapter inerente mantém chamadas existentes. T5: suíte existente de linguagem/casts/repr/show/CLI, workspace completo, build, Clippy/expectativas, Rustdoc, formato e linhagem, sob 12 GiB, swap zero e um job, sem relaxar esperados. Sem publicar release.\n'''
 dest=package/'proposed'/Path(owner);dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(proposed)
with gzip.open(package/'base.json.gz','wt') as f:json.dump(dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),status=subprocess.check_output(['git','status','--porcelain=v1'],text=True),diffstat=subprocess.check_output(['git','diff','HEAD','--stat'],text=True),owners=base),f)
(package/'proposal.diff').write_text(''.join(''.join(difflib.unified_diff(base[o]['text'].splitlines(True),(package/'proposed'/Path(o)).read_text().splitlines(True),fromfile=o,tofile=o+' (proposto)')) for o in base))
(package/'review.md').write_text('''# Proposta — Display e FromIterator\n\nQuatro contratos Rust: Display para Decimal/Duration/Version e FromIterator<Style> para Styles. Os três métodos inerentes to_string saem e as chamadas usuais passam ao ToString padrão; Styles::from_iter continua como adapter com a mesma assinatura. Os parsers Option e os next de domínio permanecem. A proposta preserva os textos atuais (incluindo Duration MIN corrigido), dobra estilos na mesma ordem e não altera defaults, campos, versão, repr Typst ou fase.\n\nOs quatro L0 completos estão em proposed/ e o delta em proposal.diff; base.json.gz preserva os owners/fontes/hashes e estado da árvore. Testes T1–T5 estão prescritos em cada owner proposto. Não inclui mudar enums públicos, FromStr, publicar release ou alterar as 48 exceções de aridade.\n\nA ADR-0127 §2 exige confirmação porque são novos contratos públicos e há migração de métodos: “alterar assinatura pública de função L1–L4” e “qualquer mudança que, se revertida depois, quebraria código já escrito contra ela (binário/API)”. Chamadas Rust usuais .to_string() continuam disponíveis pelo prelude; usuários que dependam especificamente da definição inerente precisam considerar a migração para ToString. Não aplicar os L0 ou código antes da ratificação.\n''')
(package/'manifest.sha256').write_text(''.join(f'{sha(p)}  {p.relative_to(package)}\n' for p in sorted(package.rglob('*')) if p.is_file() and p.name!='manifest.sha256'))
meta=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),review=str(package/'review.md'),manifest_sha256=sha(package/'manifest.sha256'),owners=list(contracts));(out/'public-proposal.json').write_text(json.dumps(meta,indent=2)+'\n');print(json.dumps(meta),flush=True)
